<script setup lang="ts">
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { api, type ManagedVoucherClaim, type PromotionCampaign, type PromotionDraft, type PromotionPreview, type PromotionProductReference, type PromotionRule } from '../api'
import { formatDateTime, formatVnd } from '../format'
import { t } from '../i18n'
import { blankPromotionDraft, hydratePromotionDraft, normalizePromotionCodePreview, type PromotionEditorDraft } from '../promotion-form'

const campaigns=ref<PromotionCampaign[]>([]),products=ref<PromotionProductReference[]>([]),selectedFamily=ref<string>(),query=ref('')
const editor=ref<PromotionEditorDraft>(blankPromotionDraft()),editing=ref(false),busy=ref(''),error=ref('')
const preview=ref<PromotionPreview>(),previewProductId=ref(''),previewQuantity=ref(1),previewShipping=ref(0)
const claims=ref<ManagedVoucherClaim[]>([]),claimPage=ref(0),claimsHaveNext=ref(false),claimSearch=ref(''),claimsBusy=ref(false)
const confirmDialog=ref<HTMLDialogElement>(),pendingTransition=ref<{rule:PromotionRule;action:'publish'|'retire'|'invalidate';current?:PromotionRule}>()
const revokeDialog=ref<HTMLDialogElement>(),pendingRevoke=ref<ManagedVoucherClaim>()
const visibilityPending=ref<boolean>()

const selected=computed(()=>campaigns.value.find(item=>item.familyId===selectedFamily.value))
const filtered=computed(()=>{const needle=query.value.trim().toLocaleLowerCase();return needle?campaigns.value.filter(item=>campaignName(item).toLocaleLowerCase().includes(needle)||item.familyId.includes(needle)||item.acquisitionMode.toLocaleLowerCase().includes(needle)):campaigns.value})
const layer=computed<PromotionRule['layer']>(()=>editor.value.effectType.startsWith('ITEM_')?'ITEM':editor.value.effectType.startsWith('ORDER_')?'ORDER_AUTOMATIC':'SHIPPING')
const isVoucher=computed(()=>editor.value.acquisitionMode!=='AUTOMATIC')
const effects=computed<PromotionRule['effectType'][]>(()=>isVoucher.value?['ORDER_PERCENT','ORDER_FIXED','FREE_SHIPPING']:['ITEM_PERCENT','ITEM_FIXED','ORDER_PERCENT','ORDER_FIXED','FREE_SHIPPING'])
const codePreview=computed(()=>normalizePromotionCodePreview(editor.value.normalizedCode))
const selectedTargets=computed(()=>products.value.filter(product=>editor.value.productIds.includes(product.id)))
const publishWarnings=computed(()=>selectedTargets.value.filter(product=>!product.sellable))
const campaignStatusLabels:Record<string,string>={DRAFT:'Draft',SCHEDULED:'Scheduled',ACTIVE:'Active',ENDED:'Ended',PUBLISHED:'Published',RETIRED:'Campaign retired',INVALIDATED:'Invalidated'}

function campaignName(campaign:PromotionCampaign){return campaign.currentPublished?.name??campaign.drafts[0]?.name??campaign.revisions[0]?.name??t('Untitled campaign')}
function campaignStatusLabel(status:string){return t(campaignStatusLabels[status]??status)}
function resetEditor(){editor.value=blankPromotionDraft();preview.value=undefined;previewProductId.value='';previewQuantity.value=1;previewShipping.value=0}
function beginNew(){selectedFamily.value=undefined;resetEditor();editing.value=true;visibilityPending.value=undefined}
function beginEdit(rule:PromotionRule){editor.value=hydratePromotionDraft(rule,'edit');previewProductId.value=rule.productIds[0]??products.value[0]?.id??'';preview.value=undefined;editing.value=true}
function beginRevision(rule:PromotionRule){editor.value=hydratePromotionDraft(rule,'revise');previewProductId.value=rule.productIds[0]??products.value[0]?.id??'';preview.value=undefined;editing.value=true}
function cancelEditor(){editing.value=false;resetEditor()}
function selectCampaign(campaign:PromotionCampaign){selectedFamily.value=campaign.familyId;editing.value=false;resetEditor();visibilityPending.value=undefined}

function draft():PromotionDraft{
  const item=layer.value==='ITEM',percent=editor.value.effectType.endsWith('PERCENT'),fixed=editor.value.effectType.endsWith('FIXED')
  return {familyId:editor.value.familyId,revisionNumber:editor.value.revisionNumber,name:editor.value.name.trim(),layer:layer.value,effectType:editor.value.effectType,
    percentageValue:percent?editor.value.value:undefined,fixedAmount:fixed?editor.value.value:undefined,minimumSpendAmount:editor.value.minimumSpendAmount,
    buyQuantity:item?editor.value.buyQuantity:undefined,globalUsageLimit:editor.value.globalUsageLimit,perCustomerUsageLimit:editor.value.acquisitionMode==='CLAIMABLE'?1:editor.value.perCustomerUsageLimit,
    priority:editor.value.priority,validFrom:new Date(editor.value.validFrom).toISOString(),validTo:editor.value.validTo?new Date(editor.value.validTo).toISOString():undefined,
    productIds:item?[...editor.value.productIds]:[],customerSummary:isVoucher.value?editor.value.customerSummary.trim():undefined,customerTerms:isVoucher.value?editor.value.customerTerms.trim():undefined,
    acquisitionMode:editor.value.acquisitionMode,normalizedCode:editor.value.acquisitionMode==='CODE'?codePreview.value:undefined,
    publiclyDiscoverable:editor.value.acquisitionMode==='CLAIMABLE'?true:editor.value.acquisitionMode==='AUTOMATIC'?false:editor.value.publiclyDiscoverable}
}

async function load(preferred=selectedFamily.value){busy.value='load';error.value='';try{const [campaignResult,productResult]=await Promise.all([api.promotionCampaigns(),api.promotionProducts()]);campaigns.value=campaignResult.items;products.value=productResult;selectedFamily.value=preferred&&campaigns.value.some(item=>item.familyId===preferred)?preferred:campaigns.value[0]?.familyId}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=''}}
async function save(){busy.value='save';error.value='';try{const saved=editor.value.editingId?await api.editPromotion(editor.value.editingId,draft()):await api.createPromotion(draft());editing.value=false;resetEditor();await load(saved.familyId)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=''}}
async function runPreview(){if(!previewProductId.value)return;busy.value='preview';error.value='';preview.value=undefined;try{preview.value=await api.previewPromotion(draft(),previewProductId.value,previewQuantity.value,previewShipping.value)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=''}}
async function transition(rule:PromotionRule,action:'publish'|'retire'|'invalidate'){const current=action==='publish'?selected.value?.currentPublished??undefined:undefined;pendingTransition.value={rule,action,current};await nextTick();confirmDialog.value?.showModal()}
function closeDialog(){pendingTransition.value=undefined;confirmDialog.value?.close()}
async function confirmTransition(){const pending=pendingTransition.value;closeDialog();if(!pending)return;busy.value=pending.action;error.value='';try{await api.transitionPromotion(pending.rule.id,pending.action,pending.current?.id);await load(pending.rule.familyId)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=''}}
async function updateVisibility(){if(!selected.value||visibilityPending.value===undefined)return;busy.value='visibility';error.value='';try{await api.setPromotionDiscoverability(selected.value.familyId,visibilityPending.value);visibilityPending.value=undefined;await load(selected.value.familyId)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=''}}
async function loadClaims(reset=true){if(!selected.value||selected.value.acquisitionMode!=='CLAIMABLE'){claims.value=[];claimsHaveNext.value=false;return}claimsBusy.value=true;try{const page=reset?0:claimPage.value+1;const result=await api.promotionClaims(selected.value.familyId,page,20,claimSearch.value.trim());claims.value=reset?result.items:[...claims.value,...result.items];claimPage.value=page;claimsHaveNext.value=result.hasNext}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{claimsBusy.value=false}}
async function requestRevoke(claim:ManagedVoucherClaim){pendingRevoke.value=claim;await nextTick();revokeDialog.value?.showModal()}
function closeRevokeDialog(){pendingRevoke.value=undefined;revokeDialog.value?.close()}
async function revoke(){const claim=pendingRevoke.value;closeRevokeDialog();if(!claim)return;busy.value=`revoke:${claim.claimId}`;try{await api.revokeVoucherClaim(claim.claimId);await loadClaims(true);await load(selectedFamily.value)}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=''}}

watch(()=>editor.value.acquisitionMode,mode=>{if(mode==='CLAIMABLE'){editor.value.publiclyDiscoverable=true;editor.value.perCustomerUsageLimit=1}if(mode==='AUTOMATIC'){editor.value.publiclyDiscoverable=false;editor.value.normalizedCode='';editor.value.customerSummary='';editor.value.customerTerms=''}if(!effects.value.includes(editor.value.effectType))editor.value.effectType='ORDER_FIXED'})
watch(selectedFamily,()=>void loadClaims(true))
onMounted(()=>void load())
</script>

<template>
  <div class="operations-page promotions-page">
    <header class="page-heading promotion-heading"><div><h1>{{t('Promotion campaigns')}}</h1><p>{{t('Plan, preview, publish, and inspect customer usage without changing historical order pricing.')}}</p></div><button class="primary-button" type="button" @click="beginNew">{{t('New campaign')}}</button></header>
    <p v-if="error" class="form-error" role="alert">{{error}}</p>
    <div v-if="busy==='load'" class="queue-loading" role="status" aria-live="polite"><span class="loader-mark"></span>{{t('Loading campaigns…')}}</div>
    <div v-else class="promotion-workbench">
      <aside class="campaign-rail" aria-label="Promotion campaigns">
        <label class="campaign-search"><span>{{t('Find campaign')}}</span><input v-model="query" type="search" :placeholder="t('Name, family, or acquisition')"></label>
        <p class="campaign-asof">{{t('State as of')}} <time v-if="campaigns[0]" :datetime="campaigns[0].asOf">{{formatDateTime(campaigns[0].asOf)}}</time></p>
        <button v-for="campaign in filtered" :key="campaign.familyId" type="button" class="campaign-row" :class="{active:selectedFamily===campaign.familyId}" @click="selectCampaign(campaign)"><span><strong>{{campaignName(campaign)}}</strong><small>{{campaign.acquisitionMode}} · {{campaign.drafts.length?t('{count} draft', {count:campaign.drafts.length}):t('No draft')}}</small></span><b :data-state="campaign.state">{{campaignStatusLabel(campaign.state)}}</b></button>
        <p v-if="!filtered.length" class="inline-state">{{t('No campaigns match this search.')}}</p>
      </aside>
      <main class="campaign-stage">
        <form v-if="editing" class="promotion-editor promotion-editor-sections" @submit.prevent="save">
          <header><div><h2>{{t(editor.editingId?'Edit draft':editor.familyId?'Create revision':'Create campaign')}}</h2><p>{{t('Draft changes do not alter published customer pricing.')}}</p></div><button class="text-button" type="button" @click="cancelEditor">{{t('Cancel')}}</button></header>
          <section aria-labelledby="campaign-section"><h3 id="campaign-section">{{t('Campaign')}}</h3><div class="editor-fields"><label>{{t('Name')}}<input v-model="editor.name" required maxlength="120"></label><label>{{t('Acquisition mode')}}<select v-model="editor.acquisitionMode" :disabled="!!editor.familyId"><option>AUTOMATIC</option><option>CODE</option><option>CLAIMABLE</option></select><small v-if="editor.familyId">{{t('Immutable for this family.')}}</small></label><label v-if="editor.acquisitionMode==='CODE'">{{t('Voucher code')}}<input v-model="editor.normalizedCode" :disabled="!!editor.familyId" required minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9_-]{2,31}"><small>{{t('Saved as')}} <code>{{codePreview||'—'}}</code></small></label></div></section>
          <section aria-labelledby="effect-section"><h3 id="effect-section">{{t('Effect')}}</h3><div class="editor-fields"><label>{{t('Benefit type')}}<select v-model="editor.effectType"><option v-for="effect in effects" :key="effect">{{effect}}</option></select></label><label v-if="editor.effectType!=='FREE_SHIPPING'">{{editor.effectType.endsWith('PERCENT')?t('Percentage'):t('Amount (VND)')}}<input v-model.number="editor.value" type="number" min="1" :max="editor.effectType.endsWith('PERCENT')?100:9999999999" required></label><label>{{t('Priority')}}<input v-model.number="editor.priority" type="number" required></label></div></section>
          <section aria-labelledby="eligibility-section"><h3 id="eligibility-section">{{t('Eligibility')}}</h3><div class="editor-fields"><label>{{t('Minimum spend')}}<input v-model.number="editor.minimumSpendAmount" type="number" min="0"></label><label v-if="layer==='ITEM'">{{t('Buy quantity')}}<input v-model.number="editor.buyQuantity" type="number" min="1"></label><label>{{t('Global usage limit')}}<input v-model.number="editor.globalUsageLimit" type="number" min="1"></label><label v-if="editor.acquisitionMode!=='CLAIMABLE'">{{t('Per-customer limit')}}<input v-model.number="editor.perCustomerUsageLimit" type="number" min="1"></label><p v-else class="policy-note">{{t('Claimable offers are permanently limited to one claim and one use per customer family.')}}</p></div><fieldset v-if="layer==='ITEM'" class="product-targets"><legend>{{t('Eligible products')}}</legend><label v-for="product in products" :key="product.id" class="product-target-row"><input v-model="editor.productIds" type="checkbox" :value="product.id"><span><strong>{{product.name}}</strong><small>{{product.category||t('Uncategorized')}} · {{product.publishedVariantCount}} {{t('published variants')}}</small></span><b :class="product.sellable?'status-good':'status-warning'">{{t(product.sellable?'Sellable now':'Not sellable now')}}</b></label></fieldset></section>
          <section v-if="isVoucher" aria-labelledby="acquisition-section"><h3 id="acquisition-section">{{t('Acquisition')}}</h3><div class="editor-fields"><label>{{t('Customer summary')}}<input v-model="editor.customerSummary" required maxlength="240"></label><label>{{t('Customer terms')}}<textarea v-model="editor.customerTerms" required maxlength="1000"></textarea></label><p class="policy-note">{{t(editor.acquisitionMode==='CLAIMABLE'?'Claimable offers are public. Visibility is managed live at family level after creation.':'Code offers never appear in generic public discovery.')}}</p></div></section>
          <section aria-labelledby="schedule-section"><h3 id="schedule-section">{{t('Schedule')}}</h3><div class="editor-fields"><label>{{t('Starts')}}<input v-model="editor.validFrom" type="datetime-local" required></label><label>{{t('Ends')}}<input v-model="editor.validTo" type="datetime-local"></label></div></section>
          <section aria-labelledby="preview-section"><h3 id="preview-section">{{t('Preview')}}</h3><p>{{t('Uses a current server-owned product price and the same promotion calculator as checkout. Preview creates no claim, reservation, or usage record.')}}</p><div class="editor-fields"><label>{{t('Sample product')}}<select v-model="previewProductId" required><option value="" disabled>{{t('Choose product')}}</option><option v-for="product in products" :key="product.id" :value="product.id">{{product.name}} · {{product.minimumAmount?formatVnd(product.minimumAmount):t('No published price')}}</option></select></label><label>{{t('Quantity')}}<input v-model.number="previewQuantity" type="number" min="1" max="10"></label><label>{{t('Sample shipping fee')}}<input v-model.number="previewShipping" type="number" min="0" max="9999999999"></label><button class="text-button" type="button" :disabled="busy==='preview'||!previewProductId" @click="runPreview">{{t(busy==='preview'?'Calculating…':'Calculate preview')}}</button></div><div v-if="preview" class="promotion-preview" aria-live="polite"><div><span>{{preview.product.productName}} · {{preview.product.sku}}</span><strong>{{formatVnd(preview.merchandiseAmount)}}</strong></div><div><span>{{t('Merchandise discount')}}</span><strong>−{{formatVnd(preview.merchandiseDiscountAmount)}}</strong></div><div><span>{{t('Shipping discount')}}</span><strong>−{{formatVnd(preview.shippingDiscountAmount)}}</strong></div><div class="preview-total"><span>{{t('Preview total')}}</span><strong>{{formatVnd(preview.totalAmount)}}</strong></div><small v-if="!preview.adjustments.length">{{t('This campaign does not apply to the selected sample.')}}</small></div></section>
          <section aria-labelledby="lifecycle-section"><h3 id="lifecycle-section">{{t('Lifecycle')}}</h3><p>{{t('Publishing makes this immutable and atomically retires the current published revision, if any.')}}</p><p v-if="publishWarnings.length" class="warning-note" role="note"><strong>{{t('Publish warning')}}</strong> · {{t('{count} targeted products are not currently sellable. Publishing is allowed, but customers may not be able to buy them.', {count:publishWarnings.length})}}</p><button class="primary-button" :disabled="!!busy||layer==='ITEM'&&!editor.productIds.length">{{t(busy==='save'?'Saving…':editor.editingId?'Save draft':editor.familyId?'Create revision':'Create draft')}}</button></section>
        </form>
        <template v-else-if="selected">
          <header class="campaign-detail-heading"><div><p class="campaign-family">{{selected.familyId}}</p><h2>{{campaignName(selected)}}</h2><p>{{selected.currentPublished?.customerSummary??selected.drafts[0]?.customerSummary??t('Automatic pricing campaign')}}</p></div><b :data-state="selected.state">{{campaignStatusLabel(selected.state)}}</b></header>
          <section class="campaign-summary" aria-label="Campaign summary"><dl><div><dt>{{t('Acquisition')}}</dt><dd>{{selected.acquisitionMode}}<code v-if="selected.normalizedCode">{{selected.normalizedCode}}</code></dd></div><div><dt>{{t('Current revision')}}</dt><dd>{{selected.currentPublished?`R${selected.currentPublished.revisionNumber}`:t('None')}}</dd></div><div><dt>{{t('Drafts')}}</dt><dd>{{selected.drafts.length}}</dd></div><div><dt>{{t('Targets')}}</dt><dd>{{selected.targetProducts.length||t('Order-wide')}}</dd></div></dl></section>
          <section v-if="selected.acquisitionMode!=='AUTOMATIC'" class="live-setting"><div><h3>{{t('Public discoverability')}}</h3><p>{{t(selected.acquisitionMode==='CLAIMABLE'?'Claimable campaigns must remain public to be claimable. This is a live family setting, not a draft field.':'Code campaigns remain excluded from generic public offer discovery even when this family setting is on.')}}</p></div><div v-if="visibilityPending===undefined" class="live-setting-value"><strong>{{t(selected.publiclyDiscoverable?'On':'Off')}}</strong><button v-if="selected.acquisitionMode!=='CLAIMABLE'||!selected.publiclyDiscoverable" class="text-button" type="button" @click="visibilityPending=!selected.publiclyDiscoverable">{{t('Change')}}</button></div><div v-else class="visibility-confirm" role="alert"><span>{{t('Apply this live setting now?')}}</span><button class="primary-button" type="button" :disabled="busy==='visibility'" @click="updateVisibility">{{t('Confirm')}}</button><button class="text-button" type="button" @click="visibilityPending=undefined">{{t('Cancel')}}</button></div></section>
          <section class="usage-ledger"><h3>{{t('Usage & customer evidence')}}</h3><dl><div><dt>{{t('Claims')}}</dt><dd>{{selected.usage.claimed}}</dd></div><div><dt>{{t('Reserved')}}</dt><dd>{{selected.usage.reserved}}</dd></div><div><dt>{{t('Redeemed')}}</dt><dd>{{selected.usage.redeemed}}</dd></div><div><dt>{{t('Released')}}</dt><dd>{{selected.usage.released}}</dd></div><div><dt>{{t('Paid orders')}}</dt><dd>{{selected.usage.paidAppliedOrders}}</dd></div><div><dt>{{t('Discount granted')}}</dt><dd>{{formatVnd(selected.usage.discountGranted)}}</dd></div></dl><small>{{t('Unlimited automatic promotions can have paid order adjustments without redemption rows.')}}</small></section>
          <section class="revision-ledger"><header><div><h3>{{t('Revision history')}}</h3><p>{{t('Published history is immutable. Drafts remain editable until publication.')}}</p></div><button v-if="selected.currentPublished" class="text-button" type="button" @click="beginRevision(selected.currentPublished)">{{t('Create revision')}}</button></header><ol><li v-for="revision in selected.revisions" :key="revision.id"><div><strong>R{{revision.revisionNumber}} · {{revision.name}}</strong><small>{{revision.effectType}} · {{revision.percentageValue?`${revision.percentageValue}%`:revision.fixedAmount?formatVnd(revision.fixedAmount):t('Free shipping')}} · {{formatDateTime(revision.validFrom)}}</small></div><b>{{campaignStatusLabel(revision.status)}}</b><div class="revision-actions"><button v-if="revision.status==='DRAFT'" class="text-button" type="button" @click="beginEdit(revision)">{{t('Edit')}}</button><button v-if="revision.status==='DRAFT'" class="primary-button" type="button" @click="transition(revision,'publish')">{{t('Publish')}}</button><button v-if="revision.status==='PUBLISHED'" class="text-button" type="button" @click="transition(revision,'retire')">{{t('Retire')}}</button><button v-if="revision.status==='PUBLISHED'" class="danger-button" type="button" @click="transition(revision,'invalidate')">{{t('Invalidate')}}</button></div></li></ol></section>
          <section v-if="selected.acquisitionMode==='CLAIMABLE'" class="claim-ledger"><header><div><h3>{{t('Customer claims')}}</h3><p>{{t('Searchable ownership evidence is shown before any revoke action.')}}</p></div><form @submit.prevent="loadClaims(true)"><label><span>{{t('Customer login')}}</span><input v-model="claimSearch" type="search"></label><button class="text-button" :disabled="claimsBusy">{{t('Search')}}</button></form></header><div class="table-shell"><table><thead><tr><th>{{t('Customer')}}</th><th>{{t('Claimed')}}</th><th>{{t('State')}}</th><th>{{t('Usage')}}</th><th>{{t('Action')}}</th></tr></thead><tbody><tr v-for="claim in claims" :key="claim.claimId"><td>{{claim.customerLogin}}</td><td>{{formatDateTime(claim.claimedAt)}}</td><td>{{t(claim.claimStatus)}}</td><td>{{claim.reserved}} / {{claim.redeemed}} / {{claim.released}}</td><td><button v-if="claim.claimStatus==='CLAIMED'" class="danger-button" type="button" :disabled="busy===`revoke:${claim.claimId}`" @click="requestRevoke(claim)">{{t('Revoke')}}</button></td></tr></tbody></table></div><button v-if="claimsHaveNext" class="text-button load-more" type="button" :disabled="claimsBusy" @click="loadClaims(false)">{{t(claimsBusy?'Loading…':'Load more')}}</button><p v-if="!claimsBusy&&!claims.length" class="inline-state">{{t('No claims found.')}}</p></section>
        </template>
        <section v-else class="inline-state"><h2>{{t('No promotion campaigns yet.')}}</h2><p>{{t('Create a draft to begin. Nothing reaches customers until it is published.')}}</p><button class="primary-button" @click="beginNew">{{t('Create campaign')}}</button></section>
      </main>
    </div>
    <dialog v-if="pendingTransition" ref="confirmDialog" class="terminal-dialog" aria-labelledby="promotion-dialog-title" aria-describedby="promotion-dialog-description" @cancel="closeDialog"><form method="dialog" @submit.prevent><h2 id="promotion-dialog-title">{{t(pendingTransition.action==='publish'?'Confirm publication':pendingTransition.action==='retire'?'Confirm retirement':'Confirm invalidation')}}</h2><p id="promotion-dialog-description">{{t(pendingTransition.action==='publish'?(pendingTransition.current?'Publishing will atomically retire the current revision. Scheduled dates still control when the replacement becomes active.':'Publishing makes this revision immutable. Its schedule controls customer eligibility.'):pendingTransition.action==='retire'?'Retiring stops this revision from new quotes. Historical order pricing remains unchanged.':'Invalidating stops this revision and causes open quotes to be revalidated. Historical order pricing remains unchanged.')}}</p><p v-if="pendingTransition.action==='publish'&&publishWarnings.length" class="warning-note"><strong>{{t('Sellability warning')}}</strong> · {{t('{count} targeted products are not currently sellable.', {count:publishWarnings.length})}}</p><div><button class="text-button" type="button" @click="closeDialog">{{t('Cancel')}}</button><button :class="pendingTransition.action==='invalidate'?'danger-button':'primary-button'" type="button" @click="confirmTransition">{{t(pendingTransition.action==='publish'?'Publish':pendingTransition.action==='retire'?'Retire':'Invalidate')}}</button></div></form></dialog>
    <dialog v-if="pendingRevoke" ref="revokeDialog" class="terminal-dialog" aria-labelledby="revoke-dialog-title" aria-describedby="revoke-dialog-description" @cancel="closeRevokeDialog"><form method="dialog" @submit.prevent><h2 id="revoke-dialog-title">{{t('Confirm claim revocation')}}</h2><p id="revoke-dialog-description">{{t('Revoke this saved claim? The customer will no longer be able to use it.')}}</p><div><button class="text-button" type="button" @click="closeRevokeDialog">{{t('Cancel')}}</button><button class="danger-button" type="button" @click="revoke">{{t('Revoke')}}</button></div></form></dialog>
  </div>
</template>
